const ic=(n,s=20,c='',sw=1.8)=>`<svg class="ic ${c}" width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${I[n]||''}</svg>`;

const BRAND={l2f:{icon:null,word:null},aurj:{icon:null,word:null}};
const mark=(o=org(),s=32)=>`<span class="mark lg-${o}" style="--s:${s}px" aria-hidden="true"><img src="${BRAND[o].icon||(o==='l2f'?LOGO.l2fIcon:LOGO.aurjIcon)}" alt=""></span>`;
const stack=(cls='')=>`<div class="stack-wrap"><div class="stack ${cls}"><div class="ly a" style="--i:0"></div><div class="ly b" style="--i:1"></div><div class="ly c" style="--i:2"></div><div class="ly d" style="--i:3"><span>${org()==='l2f'?'L2':'عروج'}</span></div></div></div>`;

/* SYSTEM */
function rSystem(){const sw=(n,h,r)=>`<div class="sw" style="--c:${h}"><i></i><div><b>${n}</b><span>${h}</span><br>${r}</div></div>`;
const ui=['search','bell','grid','home','check','plus','upload','download','share','move','trash','star','lock','clock','list','tiles','filter','eye','msg','mail','alert','info','xcircle','wifi','shield','team','apps','doc','folder','clip','refresh','logout','sun','moon'];
return `<div class="wrap">
<div class="hero-sys"><div><p class="over">Layer2Funnels + Aurj · Design language v3</p><h1>Ink stage.<br>Paper desk.<br><em>One signal.</em></h1><p>The Launcher is a dark stage where apps sit as dimensional plates. Inside, work happens on calm paper surfaces. Yellow is the signal: it marks the one thing that matters on a screen. Blue means “do” and “done”.</p></div>${stack()}</div>
<section class="sys-sec"><header><span class="n">01</span><h2>Principles</h2></header><div class="princ">
<div><span class="num">a</span><b>Depth means something</b><p>3D is used for things you can open, press or pick up: app icons, the main next step, dragged files. Lists and tables stay flat.</p></div>
<div><span class="num">b</span><b>Stage, then desk</b><p>Expressive at the door (Launcher, sign in, empty states). Quiet at the desk, where people work for hours.</p></div>
<div><span class="num">c</span><b>One signal per screen</b><p>Yellow appears once per screen, on the item that needs you. If everything is yellow, nothing is.</p></div>
<div><span class="num">d</span><b>Motion explains change</b><p>Things grow from where you tapped, settle with a small spring, and never make you wait more than half a second.</p></div></div></section>
<section class="sys-sec"><header><span class="n">02</span><h2>Colour</h2><p>Every colour has one job. Success is blue, never green. Neutrals are warm and never pure black or white.</p></header>
<p class="over" style="margin-bottom:10px">Layer2Funnels</p><div class="sw-row">${sw('Ink','#16171B','Text, stage, ink buttons')}${sw('Paper','#F3F1EB','Light background')}${sw('Signal','#FFC633','The one thing that needs you')}${sw('Volt','#2B63F6','Actions, links, success')}${sw('Amber text','#8A5200','Warnings, on #FFF0D2')}${sw('Brick','#BA3126','Errors, on #FCE8E4')}</div>
<p class="over" style="margin:18px 0 10px">Aurj (until brand files arrive)</p><div class="sw-row">${sw('Plum ink','#1A1317','Text, stage')}${sw('Cream','#F6F0EB','Light background')}${sw('Rose','#B0305A','Brand signal')}${sw('Teal','#0C7F95','Actions, success')}</div>
<p class="over" style="margin:18px 0 10px">App plates</p><div class="sw-row">${APPS.slice(0,12).map(a=>`<div class="sw" style="--c:linear-gradient(160deg,${a.c[0]},${a.c[1]})"><i></i><div><b>${a.name}</b><span>${a.c[1]}</span></div></div>`).join('')}</div></section>
<section class="sys-sec"><header><span class="n">03</span><h2>Type</h2><p>Bricolage Grotesque for headlines (also used by Funnel Mapper Pro, so the family feels related). Geist for the interface. Geist Mono for numbers. Aurj adds Noto Nastaliq Urdu.</p></header><div class="typescale">
<div class="ts"><small>Display · 72/0.95 · 700</small><span class="d" style="font:700 clamp(40px,6vw,72px)/.95 var(--font-d);letter-spacing:-.05em">Good evening.</span></div>
<div class="ts"><small>H1 · 44/1 · 700</small><span class="d" style="font:700 44px/1 var(--font-d);letter-spacing:-.04em">Needs your attention</span></div>
<div class="ts"><small>H2 · 22/1.2 · 700</small><span class="d" style="font:700 22px/1.2 var(--font-d)">Shared with you</span></div>
<div class="ts"><small>Body · Geist 15/1.5</small><span>Clients can’t sign in until the security tests pass. Your work is saved as you go.</span></div>
<div class="ts"><small>Label · 12 caps +12%</small><span class="over">Recent updates</span></div>
<div class="ts"><small>Numbers · Geist Mono</small><span class="mono" style="font-size:22px">$12,480 · 64.2% · 22 Oct</span></div>
<div class="ts"><small>Aurj · Nastaliq</small><span style="font:600 34px/2 var(--urdu)">عروج</span></div></div></section>
<section class="sys-sec"><header><span class="n">04</span><h2>App icons</h2><p>Each app is a pressed plate: a gradient face, a lit top edge, a darker base you can see from the front, and a soft floor shadow. Glyphs share one 2px line.</p></header>
<div class="icon-wall">${APPS.map(a=>`<figure>${plate(a,72)}<figcaption>${a.name}</figcaption></figure>`).join('')}</div>
<div class="sizes">${[96,64,44,34,28].map(s=>`<div style="display:grid;justify-items:center;gap:8px">${plate(app('clients'),s)}<small class="mono muted">${s}</small></div>`).join('')}<div style="display:grid;justify-items:center;gap:8px">${mark('l2f',64)}<small class="mono muted">L2F mark*</small></div><div style="display:grid;justify-items:center;gap:8px">${mark('aurj',64)}<small class="mono muted">Aurj mark*</small></div></div>
<p class="hint" style="margin-top:12px">* Placeholder marks. They will be replaced by your real logo files.</p></section>
<section class="sys-sec"><header><span class="n">05</span><h2>Interface icons</h2><p>24px grid, 1.8px stroke, round ends. Drawn for this system, so every icon has the same weight and corner.</p></header><div class="uiic">${ui.map(n=>`<figure>${ic(n,24)}<figcaption>${n}</figcaption></figure>`).join('')}</div></section>
<section class="sys-sec"><header><span class="n">06</span><h2>Controls</h2><p>Buttons have a visible base and sink 2px when pressed. Every target is at least 44px.</p></header>
<div class="ctrls"><button class="btn primary" data-act="toast:Primary: the main action. One per screen.">${ic('plus',18,'',2.2)}New client</button><button class="btn ink" data-act="noop">Save changes</button><button class="btn action" data-act="noop">Approve</button><button class="btn ghost" data-act="noop">Cancel</button><button class="btn quiet" data-act="noop">More options</button><button class="btn ghost" aria-disabled="true" data-act="toast:Turned-off buttons stay visible and explain why.">${ic('lock',16)}Turn on</button></div>
<div class="ctrls"><span class="pill">Not started</span><span class="pill blue">${ic('check',13,'',2.6)}Done</span><span class="pill warn">${ic('clock',13,'',2.2)}Due tomorrow</span><span class="pill brand">Needs you</span><span class="pill danger">${ic('x',12,'',2.6)}Denied</span><kbd>⌘</kbd><kbd>/</kbd></div>
<div style="max-width:380px"><div class="field"><label for="demo-f">Client name</label><input id="demo-f" placeholder="Harry Kaye PT"></div></div></section>
<section class="sys-sec"><header><span class="n">07</span><h2>Depth</h2><p>Four levels. Most of the product lives on 0 and 1.</p></header><div class="depth">
<div><div class="lv" style="background:var(--sunk);border-color:transparent">0</div><p><b>Floor.</b> Page background, wells, inputs.</p></div>
<div><div class="lv" style="box-shadow:var(--sh1)">1</div><p><b>Sheet.</b> Lists, tables, panels. Hairline edge.</p></div>
<div><div class="lv" style="box-shadow:var(--sh2)">2</div><p><b>Raised.</b> The current item, the next step, selected nav.</p></div>
<div><div class="lv" style="box-shadow:var(--sh3);transform:translateY(-8px)">3</div><p><b>Floating.</b> Menus, dialogs, toasts, dragged files.</p></div></div></section>
<section class="sys-sec"><header><span class="n">08</span><h2>Motion</h2><p>Fast out, soft landing. Only transform and opacity move. With reduced motion, changes are instant and still clear.</p></header>
<div class="mtabw"><table class="mtab"><thead><tr><th>Moment</th><th>Time</th><th>Curve</th><th>Try</th></tr></thead><tbody>
<tr><td>Press: buttons sink 2px</td><td>120ms</td><td>ease-out</td><td><button class="btn ghost sm" data-act="noop">Press me</button></td></tr>
<tr><td>Hover lift on plates, cards</td><td>240–380ms</td><td>(.22,1,.36,1)</td><td>Hover any app icon</td></tr>
<tr><td>Menus and dialogs: scale from 94%</td><td>220–300ms</td><td>spring (.34,1.56,.64,1)</td><td><button class="btn ghost sm" data-act="demo-dlg">Open dialog</button></td></tr>
<tr><td>Status change: check draws, item settles</td><td>300ms</td><td>spring</td><td><button class="btn ghost sm" data-act="demo-spring"><span class="spring-demo" id="sdemo">${ic('check',18,'',2.4)}</span></button></td></tr>
<tr><td>Signature: app opens from its own icon</td><td>480ms</td><td>(.2,.8,.2,1)</td><td><button class="btn ghost sm" data-act="nav:launcher">Go to Launcher</button></td></tr>
<tr><td>Page change: crossfade</td><td>260ms</td><td>ease-out</td><td>Use the dock</td></tr></tbody></table></div></section></div>`}

/* AUTH */
const AUTHL={signin:'Sign in',signup:'Sign up',check:'Check email',reset:'Reset',newpw:'New password',invite:'Invitation',noorg:'No organization',expired:'Session ended'};
const fld=(id,l,t='text',x='')=>`<div class="field"><label for="${id}">${l}</label><div class="inp-wrap"><input id="${id}" type="${t}" ${x}>${t==='password'?`<button type="button" class="pw-t" data-act="pw:${id}" aria-label="Show password" aria-pressed="false">${ic('eye',18)}</button>`:''}</div><p class="err" id="${id}-e" role="alert" hidden></p></div>`;
function authCard(){const s=authState;const back=`<p style="text-align:center;margin-top:16px"><button class="linkbtn" data-act="auth:signin">Back to sign in</button></p>`;
const m={
signin:`<h1>Sign in</h1><p class="lede">Use the email you were invited with.</p><button class="btn ghost full" aria-disabled="true" data-act="toast:Google sign-in is switched on at go-live.">${ic('google',18)}Continue with Google</button><div class="or">or with email</div>${fld('si-e','Email','email','autocomplete="email" placeholder="you@company.com"')}${fld('si-p','Password','password','autocomplete="current-password"')}<div style="display:flex;justify-content:flex-end;margin:-8px 0 12px"><button class="linkbtn" data-act="auth:reset">Forgot password?</button></div><button class="btn primary full" data-act="signin">Sign in ${ic('arrow',18,'',2.2)}</button><p style="text-align:center;margin-top:14px;font-size:14px" class="tx2">New here? <button class="linkbtn" data-act="auth:signup">Create an account</button></p><p class="foot-note">Signing in on its own doesn’t give you access to any organization. Membership is by invitation.</p>`,
signup:`<h1>Create your account</h1><div class="notice blue" style="margin:10px 0 20px">${ic('info',18)}<span>Creating an account doesn’t give you access to any organization. You still need an invitation.</span></div>${fld('su-n','Full name','text','autocomplete="name"')}${fld('su-e','Email','email','autocomplete="email"')}${fld('su-p','Password','password','autocomplete="new-password" aria-describedby="su-h"')}<p class="hint" id="su-h" style="margin:-8px 0 18px">At least 10 characters. A few random words works well.</p><button class="btn primary full" data-act="auth:check">Create account</button><p style="text-align:center;margin-top:14px;font-size:14px" class="tx2">Have an account? <button class="linkbtn" data-act="auth:signin">Sign in</button></p>`,
check:`${plate({id:'mail',c:['#6E98FF','#2B5CF0','#1A3BAE']},64)}<h1 style="margin-top:20px">Confirm your email</h1><p class="lede">We sent a link to <b>tabish@layer2funnels.com</b>. Open it on this device to continue.</p><button class="btn ink full" data-act="resend" id="resend">Resend email</button><button class="btn quiet full" style="margin-top:8px" data-act="auth:signup">Use a different email</button>`,
reset:`<h1>Reset your password</h1><p class="lede">Enter your email. If an account exists, you’ll get a reset link shortly.</p>${fld('rs-e','Email','email','autocomplete="email"')}<button class="btn primary full" data-act="auth:newpw">Send reset link</button>${back}`,
newpw:`<h1>Choose a new password</h1><p class="lede">You’ll use it next time you sign in.</p>${fld('np-1','New password','password','autocomplete="new-password"')}${fld('np-2','Confirm new password','password','autocomplete="new-password"')}<ul class="rules" id="rules"><li data-r="len">${ic('check',16,'',2.4)}At least 10 characters</li><li data-r="match">${ic('check',16,'',2.4)}Both passwords match</li></ul><button class="btn primary full" data-act="savepw">Save new password</button>`,
invite:`<div data-org="aurj" style="display:contents"><div style="display:flex;align-items:center;gap:12px;margin-bottom:22px">${mark('aurj',56)}<div><p class="over">Invitation</p><b style="font-size:17px">Aurj</b></div></div><h1>Join Aurj as an Editor</h1><p class="lede">Tabish Riaz invited you. Accepting adds you to Aurj only. Layer2Funnels stays separate.</p><div class="notice blue" style="margin-bottom:20px">${ic('mail',18)}<span>Signed in as <b>sara@aurj.pk</b>. This invitation was sent to that email.</span></div><button class="btn primary full" data-act="toast:Welcome to Aurj. Opening your Launcher.">Accept invitation</button><button class="btn ghost full" style="margin-top:10px" data-act="decline">Decline</button><p style="text-align:center;margin-top:12px"><button class="linkbtn" data-act="toast:Signed out.">Sign out</button></p></div>`,
noorg:`<h1>You’re signed in, but not in an organization yet</h1><p class="lede">Nothing to see until someone invites you.</p><ol class="steps"><li>Ask the person who uses this with you to invite your email.</li><li>Open the invitation email and accept it.</li><li>Your apps appear on the Launcher straight away.</li></ol><button class="btn ink full" data-act="checkinv">${ic('refresh',18)}Check for invitations</button><p class="hint" id="inv-r" role="status" style="text-align:center;margin-top:10px"></p><p style="text-align:center;margin-top:6px"><button class="linkbtn" data-act="toast:Signed out.">Sign out</button></p>`,
expired:`<h1>Your session ended</h1><p class="lede">Sign in again and we’ll take you back to Projects in Layer2Funnels.</p>${fld('ex-e','Email','email','value="tabish@layer2funnels.com" readonly')}${fld('ex-p','Password','password','autocomplete="current-password"')}<div class="notice" style="margin-bottom:18px">${ic('alert',18)}<span>Changes you hadn’t saved may not be kept.</span></div><button class="btn primary full" data-act="nav:launcher">Sign in and go back</button><button class="btn quiet full" style="margin-top:8px" data-act="auth:signin">Use a different account</button>`};
return m[s]}
function rAuth(){return `<div class="auth"><div class="auth-stage stage-screen on-stage"><div style="display:flex;align-items:center;gap:10px;font-weight:600">${mark('l2f',30)}${mark('aurj',30)}<span style="margin-left:4px">Layer2Funnels + Aurj</span></div>${stack()}<div><h2>One sign-in. Every app.</h2><p>Two organizations, kept completely apart. You only ever see what you’ve been invited to.</p><div class="float-row">${['office','clients','drive','portal','planner'].map((id,i)=>plate(app(id),46,`--i:${i};`)).join('')}</div></div></div>
<div class="auth-side"><span class="seg-l">Prototype: pick a screen</span><div class="seg" role="group" aria-label="Auth screens">${Object.entries(AUTHL).map(([k,l])=>`<button aria-pressed="${k===authState}" data-act="auth:${k}">${l}</button>`).join('')}</div><div class="auth-card panel" id="authcard">${authCard()}</div></div></div>`}

/* STATES */
function rStates(){return `<div class="wrap"><div class="pg-h"><p class="over">Shared states · every app</p><h1>When things are loading, empty, broken or off limits.</h1><p>One wording and one layout for each state, so people learn it once. Colour is never the only signal: errors have ✗, success has ✓, warnings have a triangle.</p></div><div class="spec-grid">
<div class="spec"><div class="cap">Loading</div><div class="panel" aria-busy="true">${[1,2,3].map(()=>`<div class="skrow"><span class="skel c"></span><div style="flex:1;display:grid;gap:8px"><span class="skel" style="width:70%"></span><span class="skel" style="width:40%;height:10px"></span></div></div>`).join('')}<button class="btn ink" aria-disabled="true" style="justify-self:start">Saving…</button></div></div>
<div class="spec"><div class="cap">Empty · first use</div><div class="panel cen">${stack('mini-stack')}<h3>No offers yet</h3><p>Offers you create for this client show up here.</p><button class="btn primary" data-act="noop">${ic('plus',18,'',2.2)}New offer</button></div></div>
<div class="spec"><div class="cap">No results</div><div class="panel cen"><span class="iconbtn" style="background:var(--sunk);width:56px;height:56px;border-radius:18px">${ic('search',26)}</span><h3>No matches for “refund”</h3><p>Try fewer words, or check the spelling.</p><button class="btn ghost" data-act="noop">Clear search</button></div></div>
<div class="spec"><div class="cap">Nothing for you</div><div class="panel cen"><svg class="drawn" viewBox="0 0 100 100" fill="none" stroke-width="5" stroke-linecap="round"><circle cx="50" cy="50" r="45"/><path d="M32 52l12 12 25-27"/></svg><h3>Nothing needs you right now</h3><p>Approvals and reviews assigned to you show up here.</p></div></div>
<div class="spec"><div class="cap">Error · page</div><div class="panel"><span style="color:var(--danger)">${ic('xcircle',34)}</span><h3>We couldn’t load this</h3><p>Your work is safe. Check your connection and try again.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn ink" data-act="toast:Trying again…">${ic('refresh',18)}Try again</button><button class="btn quiet" data-act="toast:Reference L2-7F3A copied for support.">Details for support</button></div></div></div>
<div class="spec"><div class="cap">Error · save</div><div class="panel"><div class="field" style="margin:0"><label for="se1">Offer name</label><input id="se1" value="Starter coaching pack" aria-invalid="true" aria-describedby="se1e"><p class="err" id="se1e">${ic('xcircle',16)}Couldn’t save. Your changes are still here. Try again.</p></div><button class="btn ink" style="justify-self:start" data-act="toast:Saved.:ok">Try again</button></div></div>
<div class="spec"><div class="cap">Offline</div><div class="panel"><div class="notice">${ic('wifi',20)}<span><b>You’re offline.</b> You can keep reading. We’ll save your changes when you’re back.</span></div><div class="skrow"><span class="skel c"></span><span class="skel" style="flex:1"></span></div></div></div>
<div class="spec"><div class="cap">Not found = no access</div><div class="panel cen"><p class="d" style="font:800 64px/1 var(--font-d);letter-spacing:-.05em;color:var(--sunk);-webkit-text-stroke:1.5px var(--line2)">?</p><h3>We couldn’t find that</h3><p>It may have moved, or you may not have access.</p><button class="btn ink" data-act="nav:office/home">Go to Office Home</button></div></div>
<div class="spec"><div class="cap">Read only</div><div class="panel"><div class="notice blue">${ic('eye',18)}<span><b>Read only.</b> Your level is Viewer. Ask an admin if you need to edit.</span></div><div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><button class="btn ghost" aria-disabled="true" aria-describedby="ro1" data-act="toast:Viewers can read but not edit.">Edit offer</button><small class="hint" id="ro1">Viewers can read but not edit.</small></div></div></div>
<div class="spec"><div class="cap">Feedback</div><div class="panel" style="background:var(--sunk);box-shadow:none"><div class="toast ok" style="animation:none">${ic('check',18,'',2.4)}<span>Copy approved. The team can start design.</span></div><div class="toast warn" style="animation:none">${ic('alert',18)}<span>Two files are still uploading. Keep this tab open.</span></div></div></div>
</div></div>`}


/* CONCEPTS */
function rConcepts(){const C=[['signal','Signal','Recommended','Ink stage at the door, warm paper desk inside. Yellow marks the one thing that needs you, blue means do and done. Tactile 3D on icons and the next step only.','Daily work for years. Feels premium without tiring the eyes.'],
['paper','Paper Studio','Calm','Editorial. Serif headlines, ink rules instead of shadows, highlighter yellow. Reads like a premium agency report.','Client-facing screens and the Portal. Less “tech”, more trust.'],
['glass','Night Glass','Most wow','Always dark. Deep navy, translucent glass panels and soft coloured light behind them. The demo-day look.','Launcher and presentations. Heavier on long workdays and older laptops.'],
['blocks','Bold Blocks','Most memorable','Thick ink outlines and hard offset shadows. Playful, loud and instantly recognisable. Close to the thick-outline Whiteboard style you liked.','A strong brand. Risky for dense tables and older users.']];
return `<div class="wrap"><div class="pg-h"><p class="over">Directions · try them live</p><h1>Four ways this ecosystem could feel.</h1><p>Each preview below is rendered in its own look. Press “Use this look” to apply it to every screen in this prototype, then walk through the dock. Colours, layouts and copy stay the same, so you compare feel, not content.</p></div><div class="cgrid">
${C.map(([k,n,tag,d,b])=>`<article class="concept"><div class="cprev" data-concept="${k}"><div class="mstage">${['office','clients','drive','portal'].map(id=>plate(app(id),48)).join('')}</div><h4>Good evening, Tabish.</h4><div class="panel"><div class="row"><span class="tic ap">${ic('check',18)}</span><div class="main"><b>Approve quiz copy v2</b><small>Harry Kaye PT</small></div><button class="btn primary sm" data-act="noop">Open</button></div><div class="row"><span class="tic rv">${ic('fmp',18)}</span><div class="main"><b>Review funnel map</b><small>Funnels</small></div><span class="pill blue">Review</span></div></div></div>
<div class="cinfo"><h3>${n} <span class="pill ${k==='signal'?'brand':''}">${tag}</span></h3><p>${d}</p><p><b>Best for:</b> ${b}</p><div class="acts">${H.dataset.concept===k?`<span class="pill blue" style="height:44px;padding:0 16px">${ic('check',16,'',2.4)}In use</span>`:`<button class="btn ink" data-act="concept:${k}">Use this look</button>`}</div></div></article>`).join('')}</div></div>`}


function toast(msg,kind='info',ms=3200){const d=document.createElement('div');d.className='toast '+kind;d.innerHTML=`${ic(kind==='ok'?'check':kind==='warn'?'alert':'info',18,'',2.2)}<span>${msg}</span>`;$('#toasts').append(d);setTimeout(()=>{d.classList.add('out');setTimeout(()=>d.remove(),300)},ms)}
let lastFocus;function dlg({icon,title,body,acts}){lastFocus=document.activeElement;$('#dlg').innerHTML=`${icon||''}<h2 id="dlgt">${title}</h2>${/^\s*</.test(body)?body:'<p>'+body+'</p>'}<div class="acts">${acts.map(([l,a,k])=>`<button class="btn ${k||'ghost'}" data-act="${a}">${l}</button>`).join('')}</div>`;$('#scrim').hidden=false;setTimeout(()=>$$('#dlg button').pop().focus(),30)}
function closeDlg(){$('#scrim').hidden=true;lastFocus?.focus?.()}
function zoom(el,a,after){if(reduce||!el){after();return}const r=el.getBoundingClientRect(),W=innerWidth,Hh=innerHeight;const o=document.createElement('div');o.className='zoom';o.style.background=`linear-gradient(160deg,${a.c[0]},${a.c[1]})`;o.style.setProperty('--g',a.g||'#FFFEFA');o.innerHTML=ic(a.id,Math.round(r.width*.47),'gl',2);document.body.append(o);const g=$('svg',o);
const ins=`inset(${r.top}px ${W-r.right}px ${Hh-r.bottom}px ${r.left}px round ${r.width*.29}px)`;
o.animate([{clipPath:ins},{clipPath:'inset(0px 0px 0px 0px round 0px)'}],{duration:480,easing:'cubic-bezier(.2,.8,.2,1)',fill:'forwards'});
g.animate([{transform:`translate(${r.left+r.width/2-W/2}px,${r.top+r.height/2-Hh/2}px)`},{transform:'translate(0,0) scale(2.2)',opacity:.9}],{duration:480,easing:'cubic-bezier(.2,.8,.2,1)',fill:'forwards'}).finished.then(()=>{after();o.animate([{opacity:1},{opacity:0}],{duration:300,easing:'ease-out',fill:'forwards'}).finished.then(()=>o.remove())})}
